-- Правила урока, раунд 3 замечаний автора (урок «To»): новый принцип «английские имена» + правка четырёх правил:
-- перевод после ответа (плюс отдельная короткая реплика про to), озвучка верного ответа (~40% звука интерфейса вместо ~65%, два правила), сцена S1 (кружок: кот крупно, без облачков, осмысленное название).
-- Идемпотентно: принцип вставляется, только если строки с таким началом текста ещё нет; правки — update по началу текста (повтор пишет тот же текст).
-- Текст тот же, что в lessonRulesDefaults.js, структура — как в lessonRulesSeed.js.
do $m$
declare so int;
begin
  select coalesce(max(sort_order), 0) into so from public.lesson_rules where category = 'principle';
  so := so + 10;
  if not exists (select 1 from public.lesson_rules where left(rule_text, 40) = $r$Имена людей в уроке английские — Kate, T$r$) then
    insert into public.lesson_rules (rule_text, sort_order, category, title, rule_group, checker, severity, bad_example, good_example)
    values ($r$Имена людей в уроке английские — Kate, Tom, Anna, Max, Sam, — а не Masha/Маша: ученик учит английский, и имя в английской фразе (в ответах, type_word, say_phrase) должно быть привычным для носителя. В русских репликах такие имена пишутся по-русски и не склоняются, если это неудобно («с Кейт», «Том пишет»).$r$, so, 'principle', $r$Английские имена в уроке$r$, $r$Задания$r$, 'judge', 'warn', $r$phrase_assembly: I talk to Masha$r$, $r$phrase_assembly: I talk to Kate$r$);
  end if;
end
$m$;

update public.lesson_rules
set rule_text = $r$Перевод после ответа: если до задания перевод не объявлен (варианты английские — «to / too / at», «I need to eat»), то после верного ответа ставь короткую живую реплику с переводом: «даа)) это переводится как {t:«…»}» (перевод — белым курсивом, как всегда; сама реплика короткая, до 8 слов). Следом отдельной короткой репликой напомни, что целевое слово делает в собранной фразе («а to тут мостик между love и travel»). Исключение: если сам модуль уже даёт перевод (варианты ответа русские — «Мы любим танцевать»; в подписи фото есть «…») — перевод не повторяй.$r$
where left(rule_text, 21) = $r$Перевод после ответа:$r$;

update public.lesson_rules
set rule_text = $r$phrase_assembly: после верной сборки фраза, пришедшая в чат, озвучивается целиком (сначала звук «верно», голос стартует на ~40% его длительности); отключается voiceAnswer: false, нет поля = включено. Озвучка берётся из библиотеки слов — фразы-ответы phrase_assembly попадают туда автоматически.$r$
where left(rule_text, 36) = $r$phrase_assembly: после верной сборки$r$;

update public.lesson_rules
set rule_text = $r$word_choice: озвучка верного варианта — поле voiceCorrect (нет поля = включено, если верный вариант английский, и выключено, если русский). Для русских вариантов («Нам нужно уйти») задай voicePhrase — английскую фразу из голосового выше («We need to leave»): без неё включение на русском молчит. Порядок озвучки верного ответа везде один: звук интерфейса, затем голос на ~40% звука.$r$
where left(rule_text, 37) = $r$word_choice: озвучка верного варианта$r$;

update public.lesson_rules
set rule_text = $r$Сцены, S1. В уроке-слове первая сцена — открывающий кружок Пита: нода scene с mode "circle" и сценой с ОДНИМ котом (characters: { a } без b, кот «Пит»). Первое сообщение урока (история) и вопрос к первому заданию — это реплики ЭТОЙ ЖЕ сцены, а не отдельные audio и photo; кот один в кадре и КРУПНО (кадр кружка по умолчанию, crop.scale 1 — кот в 3 раза крупнее прежнего), облачков с текстом в кружке нет (showBubbles и display игнорируются). Название сцены осмысленное, для админа («Кот на кухне»), а не «Два кота». Последняя сцена урока — тоже кружок Пита. Старт и Финал модуля сцен не получают. Проверяется линтером: R-scene-open.$r$
where left(rule_text, 10) = $r$Сцены, S1.$r$;
